        defense: [E(.statement, 1, "Path", "{DL} says {V} stepped into {D.his} path.")],
        role: "Athletic director",
        exam: [.direct("Tell us about your role at the school.", "\"I'm the athletic director. I oversee coaches and teams, and I was in my office when I heard shouting in the gym.\""), .direct("What did you hear in the gym that day?", "\"Shouting. I came out of my office and found {D}, a parent, and {V}, a coach, at the gym door, and {D} had just shoved {V} against the wall.\""), .direct("What does the gym camera show?", "\"{D} shoving {V} against the wall after the two argued. {V} was left with a strained shoulder, which a medical note records.\""), .direct("What was the argument about?", "\"{D}'s child was cut from the team. {D} was upset and came looking for {V} after tryouts.\""), .direct("What did you see when you came out?", "\"{D} was in the gym doorway arguing with {V}, who was holding a clipboard. Both were loud, and {V} was blocking the door.\""), .direct("What did the camera record?", "\"{D} shoves {V} against the wall with both hands. {V} falls back and then stands, holding a shoulder.\""), .cross("Had {D} been told to leave before the shove?", "\"Yes. {D} had been told to leave the gym and refused. That is what I was told.\""), .cross("Was {V} holding anything?", "\"A clipboard. {V} was holding a clipboard, not a weapon.\""), .cross("Had {D} been told to leave?", "\"Yes. {V} had asked {D} to leave twice, and I'd said the same.\""), .cross("Did {V} step into {D}'s path?", "\"{V} was standing in the doorway. I will agree {V} was in {D}'s way, but it wasn't a threat.\""), .cross("You did not see the shove itself, did you?", "\"Not the moment of contact. I heard the shouting from the hallway and saw {V} against the wall by the time I got to the door.\"")],
        defenseRole: "Equipment manager",
        defenseExam: [.direct("Please describe your role and what you saw.", "\"I'm the equipment manager. I was in the gym storage room and came out when I heard raised voices.\""), .direct("Did {V} block the door of the gym?", "\"Standing in it. {V} was right in the doorway when {D} tried to get through, and there was not much room.\""), .direct("How close were {V} and {D} when it started?", "\"Very close. They were nearly chest to chest in the doorway, with {V} holding a clipboard.\""), .direct("What did you see {D} do?", "\"{D} shoved {V} out of the way and into the wall. It was quick, and I did not see anything before it.\""), .direct("Was {V} blocking the door?", "\"Standing in it. {V} was right in the doorway with arms folded around a clipboard.\""), .direct("How close were {V} and {D}?", "\"Nearly chest to chest. They were arguing at close range, and I saw {D}'s hands go up.\""), .cross("Did {V} say anything to {D} before the shove?", "\"I did not hear. They had been arguing, and I only caught the last bit of it.\""), .cross("Was {D} trying to leave or to get at {V}?", "\"I could not say. {D} was upset, and the doorway was the way out, so it is hard to tell.\""), .cross("Did {D} apologize to {V} afterward?", "\"No. I did not hear an apology. {D} left after the athletic director arrived.\""), .cross("You were across the gym when it happened, weren't you?", "\"Yes, near the far basket. I could see both of them, but I could not hear what was said between them.\""), .cross("You cannot say whether {V} stepped in {D}'s way on purpose, can you?", "\"No. It may have been an accident. I saw the clipboard and the movement, and I did not see a clear intention either way.\"")],
