        defense: [E(.statement, 1, "Cousin", "{DL} says a cousin stored the cases.")],
        role: "Fire chief",
        exam: [.direct("Walk us through what happened at the garage.", "\"We got a call about smoke from a rented garage. When crews arrived, the fire grew, and a cache of fireworks exploded about twenty minutes later.\""), .direct("What happened at the rented garage on {DATE}?", "\"A cache of fireworks exploded. Two of my firefighters were hurt in the blast, and the fire report says fireworks were the fuel.\""), .direct("Who rented the garage?", "\"{D}. The rental agreement lists {D} as the renter.\""), .direct("What did your crews face?", "\"We thought it was an ordinary fire. The explosion was a surprise, and two firefighters were injured.\""), .direct("What injuries did your firefighters suffer?", "\"Two firefighters were hurt, one with burns and one with a concussion. Both needed hospital care.\""), .direct("What did your fire marshal find?", "\"Several cases of consumer and commercial fireworks, enough to fuel a violent blast. The garage was rented in {D}'s name.\""), .cross("{DL} says a cousin stored the goods, doesn't {D.he}?", "\"I can't say whose goods they were. I only know who rented the garage.\""), .cross("Did you see {DL} store fireworks?", "\"No. I arrived after the fire started. I can't say who stored what.\""), .cross("Was {DL} at the scene?", "\"I don't recall seeing {D}. I was focused on the crews.\""), .cross("Did you see {D} at the scene?", "\"Not at first. {D} came later and said the goods belonged to a cousin.\""), .cross("Is it illegal to store fireworks in a rented garage?", "\"It depends on the amount and type. This quantity violated the fire code and the lease.\"")],
        defenseRole: "Landlord",
        defenseExam: [.direct("What can you tell us about your property?", "\"I own the building with the garage. I rented it to {D} for storage and the lease forbids explosives or flammables.\""), .direct("Do you own the garage?", "\"Yes. I'm the landlord. I rented it to {D}.\""), .direct("Who paid for it?", "\"{D} signed the lease. I don't track who pays {D}.\""), .direct("Did you go inside?", "\"No. I never went inside after renting. It's a simple garage.\""), .direct("Who paid the rent?", "\"I received checks in {D}'s name. I don't track whether anyone else contributed.\""), .direct("Did you go inside after the rental?", "\"No. I never went inside after I handed over the key, and I should have inspected the garage once in a while, as the lease allows.\""), .cross("Did you inspect it?", "\"Not recently. I know I should have.\""), .cross("Did you know about the fireworks?", "\"No. I would have refused, because it's against the lease and the fire code.\""), .cross("Did you see anyone else use the garage?", "\"I saw a person at the garage at times during the year, but I never learned who it was or what the person carried.\""), .cross("You never went inside the garage after you rented it out, did you?", "\"No. I handed over the key and collected the rent. I did not look inside or ask what was kept there.\""), .cross("You did not know that fireworks were stored there, did you?", "\"I had no idea. If I had known, I would have refused. I learned about it when the fire crews called me.\"")],
        theory: ("{D} stored explosives.", "A cousin's goods."),
        allocution: "\"I let it get out of hand. I'm ashamed.\"",
        truths: ("{DL} sold fireworks at a roadside stand.", "The cousin paid the rent."),
        defendant: [.direct("Why did you rent the garage?", "\"I rented it as storage. A cousin used it for some goods. I didn't know what was inside.\""), .direct("Did you know about fireworks?", "\"No. I never went into the garage. If I had known, I'd have had them removed.\""), .direct("How are you coping with what happened?", "\"Terrible. Two people were hurt. I never imagined anything like that.\""), .direct("Tell us why you rented the garage.", "\"I wanted storage for tools and furniture. A cousin asked to use part of it, and I agreed.\""), .direct("Did you know what the cousin stored?", "\"I thought boxes. I never went inside after I handed over the key, and I trusted my cousin.\""), .direct("Did you sell fireworks?", "\"I sell fireworks at a roadside stand in season. I buy from a licensed supplier, and I kept those goods at my own place.\""), .cross("The garage was rented in your name, wasn't it?", "\"Yes. I'm responsible. I should have checked.\""), .cross("You never inspected it, did you?", "\"No. I trusted my cousin. That was my mistake.\""), .cross("Illegal fireworks were stored there, weren't they?", "\"So I'm told. I'm shocked. I didn't know.\""), .cross("Your cousin paid the rent. Who is the cousin?", "\"I can give a name. The cousin has left town, and I don't have a number.\""), .cross("You never opened the garage and looked at what the cousin kept in it, did you?", "\"No. I trusted my cousin and did not ask. I now know I should have checked what was being stored there.\"")],
        openings: ("A rented garage holding a cache of fireworks exploded, injuring two firefighters. {D} rented the garage. The State will show the rental agreement, the fire report, and the fire chief.", "Jurors will also see a landlord who rented only storage, a renter who never went inside, and a cousin who used the space. Listen closely to the witnesses."),
        closings: ("A garage rented by {D}, a cache of fireworks, and two firefighters hurt in the blast. The renter is responsible for what is stored in {D.his} garage.", "{D} rented storage and never knew what was inside, and the cousin who used it is gone. The State has not proved {D} knew of the fireworks."),
        timeline: [(-21, "The rental."), (0, "Noon: the fire."), (0, "12:20 p.m.: the blast."), (1, "{DL} is identified.")],
        identified: "A rental agreement.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I have burns on my hands.",
        doctrines: ["burdenOfProof"])

    static let medicSpitBiteV1 = SmallCases.make(
