        aggravating: ["The defendant was impaired at the time of the offense"],
        mitigating: ["The defendant has accepted responsibility"],
        mood: .sympathetic,
        impact: "She was my sister.",
        doctrines: ["intoxication", "lesserIncluded"])

    static let checkKitingRingV1 = SmallCases.make(
