        defense: [E(.statement, 1, "Delays", "{DL} says deposits were delayed.")],
        role: "Bank fraud officer",
        exam: [.direct("Please describe your job at the bank.", "\"I'm a bank fraud officer. I look at patterns in deposits and transfers that suggest check kiting, where money is moved between accounts to create a false balance.\""), .direct("What did the bank statements show?", "\"Overlapping deposits across two banks and checks drawn on empty accounts. {D}, a contractor, built a $38,000 float that collapsed.\""), .direct("What does the transfer log show?", "\"Daily transfers moving money between the accounts for months, to cover payroll.\""), .direct("What do the check images show?", "\"Checks from accounts with no money. One covered another, buying time.\""), .direct("What did the pattern look like?", "\"Daily transfers between accounts at two banks, overlapping deposits, and checks drawn on accounts that had no money in them.\""), .direct("How large did it get?", "\"A float of about $38,000, which collapsed when a check bounced and the other bank refused to cover the overlap.\""), .cross("{DL} says deposits were delayed, doesn't {D.he}?", "\"Posting delays are real. But daily transfers for months suggest a pattern.\""), .cross("Was payroll paid?", "\"Yes. Workers were paid. That's the purpose of the float.\""), .cross("Did {D} take money for personal use?", "\"The records show the money went to payroll. I didn't find personal withdrawals.\""), .cross("Do posting delays really happen?", "\"Yes. Deposits can take days to post, but the pattern here was too regular to be accidental.\""), .cross("You could not tell from the statements alone what {D} intended, could you?", "\"No. I can tell you what the records show. I cannot tell you what was in {D}'s mind when the checks were written.\"")],
        defenseRole: "Bookkeeper",
        defenseExam: [.direct("Tell us about your work for {D}.", "\"I'm the bookkeeper. I record deposits and payments, reconcile the bank statements, and prepare payroll.\""), .direct("Do you keep {DL}'s books?", "\"Yes. I'm the bookkeeper.\""), .direct("Were deposits delayed?", "\"Often. Checks from clients take days to clear. It's a problem in our business.\""), .direct("Were deposits delayed in that period?", "\"Often. A big client paid late that quarter, and checks from others took days to clear.\""), .direct("Did {D} understand posting times?", "\"Not well. I explained them several times, but {D} kept thinking the money would arrive sooner than it did, and kept writing checks against it.\""), .direct("What did {D} say about the float when you did the books together?", "\"{D} said it was a timing issue and that the checks would clear. I did not know how large it had grown until the bank called.\""), .cross("Did {DL} keep going?", "\"Yes. Until it collapsed.\""), .cross("Did you warn {D} about the float?", "\"I flagged it in a meeting and again in an email. I'm not sure {D} understood how risky the float had become.\""), .cross("Were the accounts empty at times?", "\"Yes. I noticed it on several statements, and it made me nervous. I told {D} we needed to stop moving checks between the banks.\""), .cross("You did not review the bank statements yourself each month, did you?", "\"Not every month. I trusted what {D} gave me and did not question it until the bank contacted me.\""), .cross("You never warned {D} in writing about the float, did you?", "\"I mentioned it in conversation. I did not send a written warning, and I regret not doing so.\"")],
        theory: ("{D} kited checks.", "Delayed deposits."),
        allocution: "\"I knew better. I want to make it right.\"",
        truths: ("{DL} was warned by one bank.", "A client paid late that quarter."),
        defendant: [.direct("Did you intend to cheat the banks?", "\"No. I wanted my crew paid. I misjudged how long deposits took.\""), .direct("Please describe your business.", "\"I run a small contracting company with eight workers. Payroll is every Friday, and I've always paid my crew on time.\""), .direct("What were you doing with the two accounts?", "\"Covering payroll while clients paid late. I deposited checks at one bank and moved money to the other, expecting deposits to post sooner.\""), .direct("What happened when it collapsed?", "\"I was shocked. One of the banks froze the account, and I couldn't pay my crew for two weeks.\""), .direct("How did the floating balance get started in the first place?", "\"A client paid late one quarter and payroll was due. I wrote a check from one account to cover the other and told myself it was temporary.\""), .direct("Why did you keep going after the first month?", "\"Because it worked. Each month I covered the one before, and it got bigger until a bank flagged it. I should have stopped sooner.\""), .cross("You moved checks between banks daily, didn't you?", "\"Yes. It was a routine. I thought of it as timing.\""), .cross("Some checks were drawn on empty accounts, weren't they?", "\"Yes. I expected deposits to cover them.\""), .cross("$38,000 was the size of the float, wasn't it?", "\"Yes. It got big. I should have stopped.\""), .cross("You moved checks between banks daily. Isn't that a routine kite?", "\"I thought of it as managing cash. I didn't know it was illegal.\""), .cross("Some checks were drawn on empty accounts. Didn't you know?", "\"I expected deposits to arrive before the checks cleared. I misjudged how long it would take.\"")],
        openings: ("{D}, a contractor, moved checks between two banks for months to cover payroll, building a $38,000 float that collapsed. The statements show overlapping deposits and checks from empty accounts. The State will present the bank fraud officer.", "The defense evidence includes a contractor who misunderstood posting delays and wanted the crew paid, and a bookkeeper who saw the confusion. Listen closely to the witnesses."),
        closings: ("Daily transfers between two banks, checks drawn on empty accounts, and a $38,000 float that collapsed. That is check kiting, and {D} did it for months.", "{D} wanted the crew paid and misjudged posting times. The State has not proved a fraudulent intent, and the money all went to payroll."),
        timeline: [(-150, "The first check."), (0, "Month 5: the collapse."), (0, "Month 5: banks notified."), (1, "{DL} is charged.")],
        identified: "Bank statements.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        doctrines: ["burdenOfProof"])

