        exam: [.direct("What did you review about {V}'s deed?", "\"{V}, eighty-six, signed a deed on {DATE} giving the farm to {D} for $1. {D} was a driver {V} had hired for appointments.\""), .direct("What do the medical records show?", "\"Dementia with frequent confusion. Doctors said {V} often could not recall the year.\""), .direct("Who notarized it?", "\"A friend of {D}. No lawyer and no relative was present. {V} died three weeks later.\""), .direct("What does your work as an estate attorney involve?", "\"I handle wills, deeds, and estates. I was asked to review the deed after the owner died, because family members asked how the farm had changed hands.\""), .direct("What did you learn about the circumstances of the signing?", "\"The deed was signed three weeks before the owner died. The notary was a friend of {D}, and no relative or lawyer was present at the signing.\""), .direct("What did you learn about the notary visits?", "\"The records show {D} drove {V} to the notary three times in the month before the deed was signed. Relatives were not told about any of those trips.\""), .cross("{DL} says {V} wanted to thank {D.him}, doesn't {D.he}?", "\"Gratitude is natural. But a person with dementia may not understand a deed.\""), .cross("Did {V} have clear moments?", "\"Possibly. Dementia fluctuates. I can't say what {V} understood that day.\""), .cross("Did family know about the deed?", "\"No. A relative was never told.\""), .cross("Did {V} ever sign a will leaving the farm to anyone?", "\"There was an earlier will that left the farm to relatives. The deed was signed afterward, and it moved the farm out of the estate.\""), .cross("Could {V} have understood the deed at the time of signing?", "\"I cannot say with certainty. Medical records show frequent confusion, but I also cannot rule out a clear moment on that particular day.\"")],
        theory: ("{D} took a farm from a patient with dementia.", "A driver who was thanked."),
        allocution: "\"I'm sorry to everyone I let down. I'll repay what I can.\"",
        truths: ("{DL} had driven {V} to the notary three times in the prior month.", "{DL} told {V}'s family that {V.he} 'was not able to manage'."),
        defendant: [.direct("Why did {V} give you the farm?", "\"{V} wanted me to have it for caring for {V.him} and driving {V.him}. {V} seemed clear that day.\""), .direct("Did you ask for it?", "\"No. {V} brought it up. I was surprised.\""), .direct("Why was your friend the notary?", "\"It was convenient. I didn't think about it. I wasn't hiding anything.\""), .direct("Walk us through how you came to drive {V}.", "\"I was hired as a driver to take {V} to appointments. Over time we talked in the car, and I came to care about {V} a great deal.\""), .direct("What did you do for {V} besides driving?", "\"I helped carry groceries, fixed things around the house, and sat with {V} after appointments. {V} had few visitors, and I was often the only one.\""), .direct("Why did {V} sign the deed to you?", "\"{V} told me more than once that the farm should go to someone who cared. I did not ask for it, and I was surprised when it came up.\""), .cross("{V} had dementia, didn't {V.he}?", "\"Yes. But {V} had good moments. That day seemed good.\""), .cross("No lawyer or relative was there, were they?", "\"No. I know it looks bad.\""), .cross("You paid $1 for a farm, didn't you?", "\"Yes. I did pay that, and it was a gift. I know that's unusual.\""), .cross("The notary was your friend. Did you pick the notary?", "\"Yes, I asked my friend because it was convenient. I did not think about how it would look, and I wish I had called a lawyer.\""), .cross("You told {V}'s family {V} was not able to manage, didn't you?", "\"Yes, I said that. I meant {V} needed help with the house and the appointments. I did not mean {V} could not understand things.\"")],
        openings: ("{V}, eighty-six and living with dementia, signed a deed giving the farm to {D}, a driver {V} had hired, three weeks before {V} died. A friend of {D} notarized it, and no lawyer or relative was present. The State will show the deed and the records.", "The defense will present a person who was cared for, who wanted to thank {D}, and who seemed clear on the day {V} signed. Listen closely to the witnesses."),
        closings: ("A farm deeded for $1 by a person with dementia, notarized by the recipient's friend, with no lawyer and no relative. That is undue influence.", "{V} wanted to thank the person who cared for {V.him}, and seemed clear that day. The State has not proved {D} unduly influenced {V}."),
        timeline: [(-60, "{D} is hired as a driver."), (-14, "The trips to the notary begin."), (0, "{V} signs the deed."), (21, "{V} dies."), (40, "A relative learns of the deed.")],
        identified: "A deed.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["V": .male])

    static let catfishSingerGiftCardsV1 = SmallCases.make(
        key: "story.catfishSingerGiftCards",
        category: .whiteCollar,
        headlines: ["Online 'Actor' Collected Gift Cards for a Fake Autograph Club", "Fans Sent $11,000"],
        law: "falsePretenses",
        threshold: 7,
        spec: "Obtained property of {V} and others by false pretenses, $11,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} posed online as a TV actor and collected $11,000 in gift cards from fans on {DATE} for an 'autograph club.' The actor's team knew of no such club. {DL} says it was a fan page.",
        state: [E(.digital, 3, "Account Records", "The account was opened by {D}."), E(.digital, 3, "Messages", "'Send a card to join.'"), E(.document, 2, "Team Statement", "No such club.")],
        defense: [E(.statement, 1, "Fan Page", "{DL} says it was a fan page.")],
        role: "Fan",
        exam: [.direct("How did you come across the account?", "\"I'm a fan of a TV actor. An account messaged fans to 'send a card to join' an autograph club.\""), .direct("What did you do?", "\"I sent a gift card because I believed it was real. Fans sent $11,000 in gift cards in all.\""), .direct("What did you learn later?", "\"The actor's team said no such club exists. The account records show {D} opened the account.\""), .direct("Describe your connection to the actor's work for the jury.", "\"I have followed the show for years and I follow the cast online. I belong to several fan groups and I tend to trust what I see there.\""), .direct("What did the messages say that you received?", "\"They said to send a gift card to join an autograph club. They promised a signed photo and a chance to meet the actor, and they pushed me to hurry.\""), .direct("How much did you send and how did you send it?", "\"I sent a gift card by message, and then another. I felt rushed, and the account kept telling me that spots in the club were limited.\""), .cross("{DL} says it was a fan page, doesn't {D.he}?", "\"I never saw anything saying fan page when I sent mine.\""), .cross("Did you check with the team first?", "\"No. In hindsight, yes. I got excited.\""), .cross("Did the account use the actor's name?", "\"Yes. It looked like the actor. That's why I trusted it.\""), .cross("Did anything in the profile say it was a fan page?", "\"Looking back, there was small print in the bio. I did not see it then, and the messages never said it was a fan page.\""), .cross("Did you ever try to confirm with the actor's team?", "\"No, not before I paid. I wish I had. After I learned the team had no such club, I reported it right away.\"")],
        defenseRole: "Online friend",
        defenseExam: [.direct("Do you know {DL} online?", "\"Yes. We chat. I knew about the fan page.\""), .direct("Was it a fan page?", "\"{D} called it that. {D} said it was for fun.\""), .direct("Did {DL} mention money?", "\"Not to me. I thought it was a hobby.\""), .direct("Walk us through how you know {D}.", "\"We met in an online group years ago and we chat most days. I have known {D} as someone who loves that show and talks about it all the time.\""), .direct("What did {D} tell you about the account?", "\"{D} said it was a fan page and that the cards were for a club. I thought it was a hobby, and {D} never said it was the actor.\""), .direct("Did you ever see {D} act in a way that seemed dishonest before this?", "\"No. {D} has always been friendly with me and never asked me for money. That is why this case surprised me when I heard about it.\""), .cross("Did {DL} tell fans it was just a fan page?", "\"I don't know. I didn't see a notice.\""), .cross("Did you see the gift card requests?", "\"Some messages. I thought they were part of the page.\""), .cross("Do you know what happened to the cards?", "\"No. I wasn't involved.\""), .cross("Did you see the messages that asked fans for gift cards?", "\"I saw a few of them. I thought they were part of running a club, and I did not think about whether fans would be confused.\""), .cross("Did you ever warn {D} that it could look like a scam?", "\"No. I did not think about it at the time. Looking back, I should have said something when the cards started coming in.\"")],
        theory: ("{D} impersonated an actor.", "A fan page."),
        allocution: "\"I got carried away.\"",
        truths: ("{DL} redeemed the cards.", "The bio said 'fan page' in small print."),
        defendant: [.direct("What was the account?", "\"A fan page I ran. I posted as a fan, and it grew. I never meant anyone to think it was official.\""), .direct("Why did you ask for cards?", "\"I thought of it as a fan club fee. I didn't think about it carefully.\""), .direct("What did you do with the cards?", "\"I kept them. I didn't spend them right away. I didn't know how to stop.\""), .direct("Explain to the jury how you came to run the account.", "\"I started a page to share news about the show. It grew fast, and I posted updates, photos, and replies to fans who wrote in.\""), .direct("Why did you ask fans for gift cards?", "\"I thought of it as a way to fund the page and to run a club with signed items. The idea grew bigger than I planned.\""), .direct("What did you do with the gift cards you collected?", "\"I redeemed them over a few weeks. I used some for the page and some for myself. I did not keep records as I know I should have.\""), .cross("The message said 'send a card to join,' didn't it?", "\"Yes. That's what I wrote. I see how it reads.\""), .cross("$11,000 is a lot of gift cards, isn't it?", "\"It is. More than I expected. I didn't think it through.\""), .cross("The actor's team knew of no such club, did they?", "\"I know. I should have checked.\""), .cross("The bio said fan page in small print. Did fans see that?", "\"Maybe not. It was in the bio, but I know many people looked only at the posts. I should have said it clearly in each message.\""), .cross("You posted as the actor, didn't you?", "\"I wrote in the actor's voice in some posts. I thought that was part of the fun, and I did not think anyone would mistake it for a real person.\"")],
        openings: ("{D} posed online as a TV actor and collected $11,000 in gift cards from fans for an 'autograph club' the actor's team knew nothing about. The State will show the account records and the messages.", "Jurors will also see a fan page that grew out of control, a friend who heard it was for fun, and no plan to take money."),
        closings: ("A fake account, a fake club, and $11,000 in gift cards from fans who believed they were sending money to join a club run by the actor. Send a card to join. The team knew nothing about it.", "A fan page that grew beyond what {D} planned, with the words fan page in the bio and a friend who heard it was a hobby. The State has not proved {D} meant to deceive anyone."),
        timeline: [(-60, "The page is made."), (0, "Month 2: cards arrive."), (0, "Month 2: the report."), (1, "{DL} is traced.")],
        identified: "Account records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        impact: "I gave up groceries.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let payrollTaxSkimV1 = SmallCases.make(
        key: "story.payrollTaxSkim",
        category: .whiteCollar,
        headlines: ["Staffing Agency Owner Kept Clients' Insurance Premiums", "Policies Lapsed Without Warning"],
        law: "embezzlement100k",
        threshold: 8,
        spec: "Embezzled over $100,000 belonging to {V} and others by a person in a position of trust, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, who ran a staffing agency, kept $168,000 in premium payments from eleven clients, and their policies lapsed. {DL} says cash flow forced the delay.",
        state: [E(.document, 3, "Bank Records", "Premiums moved to {D}'s account."), E(.document, 3, "Client Contracts", "{D} handled the premiums."), E(.document, 2, "Lapse Notices", "Eleven lapses.")],
        defense: [E(.statement, 1, "Cash Flow", "{DL} says cash flow forced the delay.")],
        role: "Client business owner",
        exam: [.direct("What did you hire {D}'s staffing agency to do for you?", "\"Handle our insurance premium payments. {D}'s contract with our company says {D} handled the premiums.\""), .direct("What happened to the insurance policies after that?", "\"They lapsed. Eleven clients got lapse notices because the premiums were not paid, and we lost coverage for months.\""), .direct("What do the bank records show about the premium money?", "\"Premiums moved to {D}'s own account. In all, $168,000 from eleven clients was moved before the lapses.\""), .direct("Please describe your business and why you hired {D}.", "\"I run a small company with about forty employees. We did not have the time to handle insurance paperwork, so we paid {D}'s agency to manage the premiums.\""), .direct("How did you learn about the lapse?", "\"I got a notice that our policy had lapsed for nonpayment. I called {D}, who said it was a mix-up, and then I learned others got the same notice.\""), .direct("What happened to you because of the lapse?", "\"We had a claim during the gap and it was denied. We had to pay it ourselves, and it was a hard stretch for our company.\""), .cross("{D} says cash flow forced the delay in payments, doesn't {D.he}?", "\"Yes. A vendor says there was a delay in payments, and I will agree with that part of the story.\""), .cross("Did {D} ever return any part of the premium money?", "\"Half was paid back, but only after the report was made. It did not come back before then.\""), .cross("Did {D} tell you about the delay before the lapse notices?", "\"No. We learned about it from the lapse notices. {D} never called us to say anything was wrong.\""), .cross("Did {D} ever tell you the premiums would be late?", "\"Not before the lapse. After it, {D} told me cash flow was tight, and I had not heard anything like that earlier.\""), .cross("Did {D} repay your company later?", "\"Some of it, after the report was filed. I do not know exactly how much of the total came back, and our losses were bigger than that.\"")],
        defenseRole: "Accounting vendor",
        defenseExam: [.direct("Was there a delay in the premium payments to insurers?", "\"Yes. Payments were delayed for a few months, and I saw {D} struggle with the cash on hand.\""), .direct("Was half of the money returned to the clients later on?", "\"Yes. Half was returned, but only after the report was made. It came back in a single wire.\""), .direct("What did {D} tell you about the money and the delays?", "\"That cash flow was tight, and that {D} would fix it. I believed {D} at the time.\""), .direct("Tell the jury how you know {D}.", "\"I run the accounting side for vendors who work with {D}'s agency. I have seen how the agency handles payments, and I worked with {D} for several years.\""), .direct("What did you see about the agency's cash flow that year?", "\"Several large clients paid late, and the agency fell behind on payables, including mine. {D} told me about it and asked for patience.\""), .direct("What did {D} say about the lapses once they happened?", "\"{D} called me upset and said the policies had lapsed. {D} said there was a plan to repay and that half had already gone back.\""), .cross("Did you personally see the bank records for the premiums?", "\"I saw some of them. They showed premiums moved to {D}'s account, which I did not like.\""), .cross("Did {D} tell the clients about the delay in payments?", "\"Not that I know of. I do not think {D} told any of the clients, and I think that was a mistake.\""), .cross("Is cash flow a good reason to use clients' premium money?", "\"No. It is not. I would not do that, and no one in my business should.\""), .cross("Did you ever see {D} spend client money on personal items?", "\"I did not see that directly. I only saw the agency's invoices and payments. I cannot speak to what happened in the bank accounts.\""), .cross("Did {D} tell the clients about the delays before the policies lapsed?", "\"I do not know. I was not involved in those calls. I only know what {D} told me after the notices went out.\"")],
        theory: ("{D} kept clients' premiums.", "A cash flow delay."),
        allocution: "\"I took advantage of someone who trusted me, and I'm sorry.\"",
        truths: ("{DL} bought a boat.", "{DL} paid half back."),
        defendant: [.direct("Did you keep your clients' premium payments?", "\"I used them to cover cash flow. I meant to pay the premiums once I caught up.\""), .direct("Why did the policies lapse?", "\"The premiums were late. I was behind, and I could not catch up in time.\""), .direct("Did you repay any of the money?", "\"Yes. I paid half back after the report. I am working on the rest.\""), .direct("Tell the jury how your agency worked.", "\"We handled payroll and insurance premiums for small companies. Clients sent the money to us, and we passed premiums to the insurers each month.\""), .direct("How did your cash flow problem start?", "\"A large client paid late and several others followed. I covered payroll first and meant to catch up on premiums within a few weeks.\""), .direct("What did you do once you knew policies had lapsed?", "\"I called the clients and told them. I paid half back after the report and I was working on a plan to repay the rest.\""), .cross("You bought a boat during the same period, didn't you?", "\"Yes. It was a bad choice. I should have saved the money.\""), .cross("$168,000 from eleven clients moved to your own account. Isn't that theft?", "\"I used it as a loan. I know that was wrong.\""), .cross("You did not tell clients about the delay, did you?", "\"No. I was embarrassed. In hindsight, yes.\""), .cross("You moved the premium money to your own account, didn't you?", "\"Yes. Premiums went into our main account, where all the money went. I understand now that was wrong, and I should have kept it separate.\""), .cross("You bought a boat that same year, didn't you?", "\"Yes, I did. It was a poor decision. I did not use client money for it on purpose, but I see why the jury may think so.\"")],
        openings: ("{D}, who ran a staffing agency, moved $168,000 in premium payments from eleven clients into {D}'s own account, and the clients' policies lapsed. {D} later bought a boat and paid half back only after a report.", "The defense case is that cash flow forced a delay, that {D} meant to pay the premiums, and that half was repaid."),
        closings: ("$168,000 in premiums moved to {D}'s account, eleven policies lapsed, a boat bought, and half repaid only after a report. Clients lost their coverage.", "A staffing agency that ran short of cash and paid back half. The State must prove {D} meant to steal, and a cash flow problem is not intent."),
        timeline: [(-365, "Premiums move."), (0, "Year 1: lapses."), (0, "Year 1: clients complain."), (1, "{DL} is charged.")],
        identified: "Bank records.",
        aggravating: ["The defendant took advantage of a position of trust or confidence", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "We nearly closed.",
        doctrines: ["burdenOfProof"])

    static let hospiceMorphineSwapV1 = SmallCases.make(
        key: "story.hospiceMorphineSwap",
        category: .whiteCollar,
        headlines: ["Home Health Nurse Replaced Dying Patients' Pain Patches With Placebos", "Families Hear Moaning All Night"],
        law: "prescriptionFraud",
        threshold: 8,
        spec: "Obtained controlled substances by fraud and deception from {V}, a home health agency, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Patients on a home health route reported uncontrolled pain. Counts showed patches missing on {D}'s visits and replaced by placebos on {DATE}. {DL} says the counts were wrong.",
        state: [E(.forensic, 3, "Patch Tests", "Placebos in six boxes."), E(.digital, 3, "Visit Logs", "Shortages on {D}'s visits."), E(.statement, 2, "Family", "'Dad was moaning.'")],
        defense: [E(.statement, 1, "Counts", "{DL} says the counts were wrong.")],
        role: "Agency director",
        exam: [.direct("What did patients on your home health route report?", "\"Uncontrolled pain. Families told us their loved ones were suffering even though they were supposed to have pain patches.\""), .direct("What did your counts show?", "\"Patches missing on {D}'s visits. The visit logs show shortages tied to those visits.\""), .direct("What did the patch tests show?", "\"Placebos in six boxes. Real pain patches had been replaced.\""), .direct("Tell us about your role as director of the agency.", "\"I run a home health agency with about thirty aides and nurses. I am responsible for patient safety, staffing, and the controlled substance counts.\""), .direct("What prompted the audit?", "\"Several families said their loved ones were in uncontrolled pain. Our counts looked off, and I ordered a full audit of patches on every route.\""), .direct("What did the audit and the lab tests show?", "\"Patches were missing on certain visits, and six boxes tested as placebos. The real pain medicine had been replaced with a look-alike patch.\""), .cross("{DL} says the counts were wrong, doesn't {D.he}?", "\"Counts can have errors. But placebos in six boxes are not a count error.\""), .cross("Did other staff visit those patients?", "\"Some. {D}'s visits stand out, but not exclusively.\""), .cross("Did anyone see {DL} swap patches?", "\"No. No one did. I rely on the logs and the tests.\""), .cross("Did several staff members have access to the patches?", "\"Yes. Several nurses and aides signed for patches on that route. I cannot say who had access at the moment each box was handled.\""), .cross("Did anyone else have shortages on their visits?", "\"A few counts were off for other staff too, but the largest pattern of shortages was on {D}'s visits. I cannot say what caused each one.\"")],
        defenseRole: "Agency aide",
        defenseExam: [.direct("Do you work on the route?", "\"Yes. I'm an aide. I see many of the same patients.\""), .direct("Who handled patches?", "\"Several of us. We all signed for them.\""), .direct("How was {DL} with patients?", "\"Kind and careful. I never saw anything wrong.\""), .direct("Please tell us about your job on the route.", "\"I am an aide on the same route. I visit patients every week, and I handle patches and counts the same way every other staff member does.\""), .direct("How were the counts done on busy days?", "\"We counted quickly. On busy days we signed for patches while we were walking in. It was not the careful process the policy describes.\""), .direct("How would you describe {D} as a coworker?", "\"Kind and careful with patients. I watched {D} sit with patients who were in pain, and I never saw anything wrong during any visit.\""), .cross("Were you on visits with {DL}?", "\"Sometimes. I can't say always.\""), .cross("Could someone else swap patches?", "\"In theory. Several had access. I didn't.\""), .cross("Were counts rushed?", "\"Yes. We were busy. Counts weren't perfect.\""), .cross("Did you ever see anyone else handle patches alone?", "\"Yes. Several staff handled patches alone, and I cannot say who handled each box on each day. We trusted the signatures.\""), .cross("Did you ever swap any patches yourself?", "\"No. I would never do that. I do know that anyone who handled the boxes could have done it, because there was no second check.\"")],
        theory: ("{D} took patches.", "Wrong counts."),
        allocution: "\"I needed help.\"",
        truths: ("{DL} had a history of back pain.", "Another nurse signed some counts."),
        defendant: [.direct("Did you take patches?", "\"No. I never took any. I cared for those patients.\""), .direct("Why do the counts show shortages on your visits?", "\"The counts were wrong. I had a heavy route, and errors happened.\""), .direct("What do you know about placebos?", "\"Nothing. I never swapped anything. I'm horrified.\""), .direct("Please describe your work with these patients.", "\"I have worked in home health for years. I care about my patients, and I visit many homes in a week, often with little time between stops.\""), .direct("How do the counts work on a visit?", "\"We count the patches at the start and sign for them. Then we count again at the end. When we are rushed, mistakes can happen.\""), .direct("What did you do when you heard about the placebos?", "\"I was horrified. I told the director I had never swapped anything, and I offered to answer every question the investigators had.\""), .cross("Six boxes had placebos, didn't they?", "\"That's what the tests show. I don't know who did it.\""), .cross("Patients suffered, didn't they?", "\"I know. I'm heartbroken. I'd never want that.\""), .cross("The shortages were on your visits, weren't they?", "\"Many were, yes. I had a heavy route with many patients on pain medicine. More visits means more counts, and more chances for errors.\""), .cross("You have a history of back pain, don't you?", "\"Yes, I do. I have had back problems for years. I have never taken a patient's medicine, and I would not do that to anyone.\""), .cross("Counts were short on your visits, not on the other nurse's, weren't they?", "\"Some were, yes. I did not take them. The other nurse signed some counts too, and I cannot explain every number.\"")],
        openings: ("Patients on a home health route reported uncontrolled pain, counts showed patches missing on {D}'s visits, and tests found placebos in six boxes. The State will present the agency director and a family.", "The defense will point you to a busy route where several staff handled patches, counts that were rushed, and no witness to any swap. Listen closely to the witnesses."),
        closings: ("Missing patches on {D}'s visits and placebos in six boxes. Patients who needed real medicine went without it, and families heard their loved ones moan in pain. The records point to {D}.", "Several staff handled those patches, the counts were hurried, and no one saw {D} take anything. The State has not proved {D} swapped a single patch, and doubt means not guilty."),
        timeline: [(-60, "Complaints begin."), (0, "Week 8: the audit."), (0, "Week 8: patches tested."), (1, "{DL} is suspended.")],
        identified: "Patch tests.",
        aggravating: ["The victim was particularly vulnerable", "The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "He suffered at the end.",
        doctrines: ["burdenOfProof"],
        genders: ["V": .male])

    static let courierDriveUpRobberyV1 = SmallCases.make(
        key: "story.courierDriveUpRobbery",
        category: .robbery,
        headlines: ["Armed Pair Take Armored Courier's Satchel Outside Grocery Store, Fleeing in Gray Van", "Delivery Schedule Found in Former Guard's Car"],
        law: "dangerousRobbery",
